/* Log:
    26. Sep. 2017  let version.
    30. Sep. 2017  function fix(CIELAB -> conversion method)
     1. Oct. 2017  function fix(that calculation by processing.js may not beef correct if you write function suffix(e.g. 2.4), therefore deleted all suffixes)
*/

let IDEAL_FRAME_RATE = 31.0;

let ambientLightBrightness = 208.0;
let directionalLightBrightness = 48.0;

let myActorSystem;
let viewer;
let paused;

function setup() {
  createCanvas(800, 800, WEBGL);
  frameRate(IDEAL_FRAME_RATE);
  sphereDetail(70);

  initialize();
}

function draw() {
  background(0.0);
  ambientLight(ambientLightBrightness, ambientLightBrightness, ambientLightBrightness);
  directionalLight(directionalLightBrightness, directionalLightBrightness, directionalLightBrightness, 0, 0, -1);

  viewer.applyPerspective();
  viewer.translateCoordinates();
  viewer.rotateCoordinates();

  noFill();
  stroke(224.0, 160.0, 224.0);
  box(0.0);

  myActorSystem.run();
}

function mouseDragged() {
  if (paused) return;
  viewer.processMouseDragged();
}

function keyPressed() {
  if (key == ' ') {
    if (paused) loop();
    else noLoop();
    paused = !paused;
  }

  if(key == CODED && keyCode == 123) initialize();  // let key
}

function initialize() {
  // prepare field
  let myPhysicsSystem = new ForceFieldPhysicsSystem();
  myPhysicsSystem.forceFieldList.add(new LorentzField(10.0, 28.0, 8.0 / 3.0, 0.0, 0.0, -25.0, IDEAL_FRAME_RATE, 0.1));
  myActorSystem = new NaiveActorSystem(myPhysicsSystem, 1024);

  // prepare view angle controller
  viewer = new ViewAngleController(radians(75.0), radians(-15.0), PI / 30.0, QUARTER_PI, IDEAL_FRAME_RATE, 0.0);
  viewer.addMouseDragChecker(new HorizontalMouseDragChecker(new AddZRotation(), -0.3));
  viewer.addMouseDragChecker(new VerticalMouseDragChecker(new AddXRotation(), -0.3));

  // prepare particle displayers
  ArrayList<PhysicsBodyDisplayer> displayerList = new ArrayList<PhysicsBodyDisplayer>();
  let anglePartitionCount = 24;
  let lightness = 88.0;
  let distanceFromZero = 64.0;
  for(i = 0; i < anglePartitionCount; i++) {
    let hueAngle = i * TWO_PI / anglePartitionCount;
    displayerList.add(new SphereDisplayer(0.5, cielabColor(lightness, distanceFromZero * cos(hueAngle), distanceFromZero * sin(hueAngle))));
  }

  // prepare particles
  let particleNumber = 1000;
  for (i = 0; i < particleNumber; i++) {
    let newActor = new NaiveBodyActor3D();
    let distance = pow(random(13.0), 0.5) * 30.0;
    let theta = random(TWO_PI);
    let phi = random(TWO_PI);
    newActor.xPosition = distance * cos(theta) * cos(phi);
    newActor.yPosition = distance * cos(theta) * sin(phi);
    newActor.zPosition = distance * sin(theta);

    newActor.displayer = displayerList.get(int(map(theta, 0.0, TWO_PI, 0.0, displayerList.size())));;

    myActorSystem.registerNewActor(newActor);
  }
}

