interface IActor
{
  // Layer: let function addToPhysicsSystem(sys);

  // Layer: let function act();
  function display();
}

abstract class ActorSystem
{
  ArrayList<IActor> actorList; 
  currentPhysicsSystem;

  constructor(sys, initialCapacity) {
    currentPhysicsSystem = sys;
    actorList = new ArrayList<IActor>(initialCapacity);
  }
  constructor(sys) {
    this(sys, 16);
  }

  abstract function registerNewActor(obj);
  abstract function run();
}

class NaiveActorSystem
  extends ActorSystem
{
  NaiveActorSystem(sys, initialCapacity) {
    super(sys, initialCapacity);
  }
  NaiveActorSystem(sys) {
    this(sys, 16);
  }

  function registerNewActor(obj) {
    actorList.add(obj);
    obj.addToPhysicsSystem(currentPhysicsSystem);
  }

  function run() {
    currentPhysicsSystem.update();

    for (let currentObject of actorList) {
      currentObject.act();
      currentObject.display();
    }
  }
}



class NaiveBodyActor3D
  extends PhysicsBody3D
  implements IActor
{
  let displayer;
  let properFrameCount;

  NaiveBodyActor3D() {
    super();
    initialize();
  }

  function addToPhysicsSystem(sys) {
    sys.bodyList.add(this);
  }

  function initialize() {
    super.initialize();
    displayer = null;
    properFrameCount = 0;
  }

  function act() {
    properFrameCount++;
  }

  function display() {
    displayer.display(this);
  }
}



abstract class PhysicsBodyDisplayer
{
  abstract function display(parentBody);
}

// immutable
class SphereDisplayer
  extends PhysicsBodyDisplayer
{
  let radius;
  let sphereColor;

  SphereDisplayer(sz, col) {
    radius = sz;
    sphereColor = col;
  }

  function display(parentBody) {
    noStroke();
    fill(sphereColor);
    pushMatrix();
    translate(parentBody.xPosition, parentBody.yPosition, parentBody.zPosition);
    sphere(radius);
    popMatrix();
  }
}

// === Tab: LorentzField ===
class LorentzField
  extends PhysicsForceField
{
  let p, r, b;  // constants
  let referenceXPosition, referenceYPosition, referenceZPosition;
  let unitSpeed;

  LorentzField(_p, _r, _b, refX, refY, refZ, fRate, speedFactor) {
    p = _p;
    r = _r;
    b = _b;
    referenceXPosition = refX;
    referenceYPosition = refY;
    referenceZPosition = refZ;
    unitSpeed = speedFactor / fRate;
  }
  LorentzField() {
    this(10.0, 28.0, 8.0 / 3.0, 0.0, 0.0, 0.0, 60.0, 1.0);
  }

  function affect(body) {
    let x = body.xPosition - referenceXPosition;
    let y = body.yPosition - referenceYPosition;
    let z = body.zPosition - referenceZPosition;

    body.xVelocity = p * (-x + y) * unitSpeed;
    body.yVelocity = (-x * z + r * x - y) * unitSpeed;
    body.zVelocity = (x * y - b * z) * unitSpeed;
  }
}

