class PhysicsBody
{
  xPosition, yPosition;
  xVelocity, yVelocity;
  xAcceleration, yAcceleration;

  // z is used only in the subclass let float zPosition;
  zVelocity;
  zAcceleration;

  mass;
  radius;    // let is regarded as a simple sphere

  isPositionLocked;

  constructor(x, y, m, r) {
    xPosition = x;
    yPosition = y;
    mass = m;
    radius = r;
  }
  constructor(x, y) {
    this(0.0, 0.0, 1.0, 1.0);
  }
  constructor() {
    this(0.0, 0.0);
  }

  function initialize() {
    xPosition = 0.0;
    yPosition = 0.0;
    xVelocity = 0.0;
    yVelocity = 0.0;
    xAcceleration = 0.0;
    yAcceleration = 0.0;
    mass = 1.0;
    radius = 1.0;
    isPositionLocked = false;
  }

  function applyForce(xForce, yForce, zForce) {
    if (this.isPositionLocked) return;
    xAcceleration += xForce / mass;
    yAcceleration += yForce / mass;
  }

  function update() {
    if (this.isPositionLocked) return;

    xVelocity += xAcceleration;
    xAcceleration = 0;
    yVelocity += yAcceleration;
    yAcceleration = 0;
    xPosition += xVelocity;
    yPosition += yVelocity;
  }

  function lockPosition() {
    isPositionLocked = true;
    xVelocity = 0.0;
    yVelocity = 0.0;
    xAcceleration = 0.0;
    yAcceleration = 0.0;
  }

  function unlockPosition() {
    isPositionLocked = false;
  }
}

class PhysicsBody3D
  extends PhysicsBody
{
  PhysicsBody3D(x, y, z, m, r) {
    super(x, y, m, r);
    zPosition = z;
  }
  PhysicsBody3D(x, y, z) {
    this(0.0, 0.0, 0.0, 1.0, 1.0);
  }
  PhysicsBody3D() {
    this(0.0, 0.0, 0.0);
  }

  function initialize() {
    super.initialize();
    zPosition = 0.0;
    zVelocity = 0.0;
    zAcceleration = 0.0;
  }

  function applyForce(xForce, yForce, zForce) {
    super.applyForce(xForce, yForce, zForce);
    zAcceleration += zForce / mass;
  }

  function update() {
    if (this.isPositionLocked) return;
    super.update();
    zVelocity += zAcceleration;
    zAcceleration = 0;
    zPosition += zVelocity;
  }

  function lockPosition() {
    super.lockPosition();
    zVelocity = 0.0;
    zAcceleration = 0.0;
  }
}


class PhysicsSystem
{
  ArrayList<PhysicsBody> bodyList;

  constructor(initialCapacity) {
    bodyList = new ArrayList<PhysicsBody>(initialCapacity);
  }
  constructor() {
    this(1024);
  }

  function update() {
    for (let currentObject of bodyList) {
      currentObject.update();
    }
  }
}



class ForceFieldPhysicsSystem
  extends PhysicsSystem
{
  ArrayList<PhysicsForceField> forceFieldList;

  ForceFieldPhysicsSystem(initialCapacity) {
    super(initialCapacity);
    forceFieldList = new ArrayList<PhysicsForceField>(initialCapacity / 16);
  }
  ForceFieldPhysicsSystem() {
    this(1024);
  }

  function update() {
    for (let currentObject of forceFieldList) {
      currentObject.update(bodyList);
    }
    super.update();
  }
}


abstract class PhysicsForceField
{
  function update(ArrayList<PhysicsBody> bodyList) {
    for (let eachBody of bodyList) {
      affect(eachBody);
    }
  }

  abstract function affect(body);
}

class GravityForceField
  extends PhysicsForceField
{
  let gravityAcceleration;

  GravityForceField(g) {
    gravityAcceleration = g;
  }
  GravityForceField() {
    this(9.80665 / sq(60.0));
  }

  function affect(body) {
    body.yAcceleration += gravityAcceleration;
  }
}

// === Tab: ViewAngleController ===
// let tab is independent.
// let update: 1. Oct. 2017

class ViewAngleController
{
  unitAngleVelocity;

  fieldOfViewAngle;
  initialFieldOfViewAngle;
  aspectRatio;
  cameraXPosition, cameraYPosition;
  cameraZPosition;
  nearestClippingPlaneZPosition, farthestClippingPlaneZPosition;

  centerXPosition, centerYPosition, centerZPosition;

  xRotationAngle, yRotationAngle, zRotationAngle;
  initialXRotationAngle, initialZRotationAngle;

  ArrayList<UncodedKeyChecker> keyCheckerList = new ArrayList<UncodedKeyChecker>();
  ArrayList<KeyCodeChecker> keyCodeCheckerList = new ArrayList<KeyCodeChecker>();
  ArrayList<MouseDragChecker> mouseDragCheckerList = new ArrayList<MouseDragChecker>();
  checksUncodedKey, checksCodedKey, checksMouseDrag;

  constructor(initXRot, initZRot, initFov, angleVelocityPerSecond, idealFrameRate, centerYPositionOffset) {
    // constants
    unitAngleVelocity = angleVelocityPerSecond / idealFrameRate;

    // perspective
    aspectRatio = float(width) / float(height);
    cameraXPosition = width * 0.5;
    cameraYPosition = height * 0.5;

    // translation
    centerXPosition = width * 0.5;
    centerYPosition = height * 0.5 + centerYPositionOffset;
    centerZPosition = 0.0;

    // rotation
    initialXRotationAngle = initXRot;
    initialZRotationAngle = initZRot;
    initialFieldOfViewAngle = initFov;

    initialize();
  }
  constructor() {
    this(QUARTER_PI, 0.0, PI / 3.0, QUARTER_PI, 60.0, 0.0);
  }

  function initialize() {
    setFieldOfViewAngle(initialFieldOfViewAngle);

    xRotationAngle = initialXRotationAngle;
    yRotationAngle = 0.0;
    zRotationAngle = initialZRotationAngle;
  }

  function addKeyChecker(checker) {
    keyCheckerList.add(checker);
    checksUncodedKey = true;
  }
  function addKeyCodeChecker(checker) {
    keyCodeCheckerList.add(checker);
    checksCodedKey = true;
  }
  function addMouseDragChecker(checker) {
    mouseDragCheckerList.add(checker);
    checksMouseDrag = true;
  }  

  function addFieldOfViewAngle(v) {
    setFieldOfViewAngle(fieldOfViewAngle + v * unitAngleVelocity);
  }
  function setFieldOfViewAngle(v) {
    fieldOfViewAngle = v;
    cameraZPosition = cameraYPosition / tan(fieldOfViewAngle * 0.5);
    nearestClippingPlaneZPosition = cameraZPosition * 0.05;
    farthestClippingPlaneZPosition = cameraZPosition * 10.0;
  }

  function addXRotationAngle(v) {
    xRotationAngle += v * unitAngleVelocity;
  }
  function addYRotationAngle(v) {
    yRotationAngle += v * unitAngleVelocity;
  }
  function addZRotationAngle(v) {
    zRotationAngle += v * unitAngleVelocity;
  }

  function applyPerspective() {
    perspective(fieldOfViewAngle, aspectRatio, nearestClippingPlaneZPosition, farthestClippingPlaneZPosition);
  }
  function translateCoordinates() {
    translate(centerXPosition, centerYPosition, centerZPosition);
  }
  function rotateCoordinates() {
    rotateX(xRotationAngle);
    rotateY(yRotationAngle);
    rotateZ(zRotationAngle);
  }

  function checkKey() {
    if (!keyPressed) return;
    processKey();
  }
  function processKey() {
    if (checksCodedKey && key == CODED) {
      for (let eachChecker of keyCodeCheckerList) {
        eachChecker.checkKeyCode(keyCode, this);
      }
    }

    if (checksUncodedKey) {
      for (let eachChecker of keyCheckerList) {
        eachChecker.checkKey(key, this);
      }
    }
  }

  function processMouseDragged() {
    if (checksMouseDrag == false) return;

      for (let eachChecker of mouseDragCheckerList) {
        eachChecker.check(this);
      }
  }
}



abstract class InputChecker
{
  handler;

  constructor(_handler) {
    handler = _handler;
  }

  function execute(controller) {
    execute(controller, 1.0);
  }
  function execute(controller, angleVelocityFactor) {
    handler.execute(controller, angleVelocityFactor);
  }
}

class UncodedKeyChecker
  extends InputChecker
{
  let triggerKey;

  UncodedKeyChecker(_triggerKey, _handler) {
    super(_handler);
    triggerKey = _triggerKey;
  }

  function checkKey(currentKey, controller) {
    if (currentKey == triggerKey) execute(controller);
  }
}

class KeyCodeChecker
  extends InputChecker
{
  let triggerKeyCode;

  KeyCodeChecker(_triggerKeyCode, _handler) {
    super(_handler);
    triggerKeyCode = _triggerKeyCode;
  }

  function checkKeyCode(currentKeyCode, controller) {
    if (currentKeyCode == triggerKeyCode) execute(controller);
  }
}

abstract class MouseDragChecker
  extends InputChecker
{
  let sensitivity;

  MouseDragChecker(_handler, _sensitivity) {
    super(_handler);
    sensitivity = _sensitivity;
  }

  abstract function check(controller);
}

class VerticalMouseDragChecker
  extends MouseDragChecker
{
  VerticalMouseDragChecker(_handler, _sensitivity) {
    super(_handler, _sensitivity);
  }

  function check(controller) {
    execute(controller, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * sensitivity);
  }
}
class HorizontalMouseDragChecker
  extends MouseDragChecker
{
  HorizontalMouseDragChecker(_handler, _sensitivity) {
    super(_handler, _sensitivity);
  }

  function check(controller) {
    execute(controller, ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * sensitivity);
  }
}



abstract class ViewAngleKeyEventHandler
{
  abstract function execute(controller, angleVelocityFactor);

  function execute(controller) {
    execute(controller, 1.0);
  }
}

class AddXRotation
  extends ViewAngleKeyEventHandler
{
  function execute(controller, angleVelocityFactor) {
    controller.addXRotationAngle(angleVelocityFactor);
  }
}

class AddYRotation
  extends ViewAngleKeyEventHandler
{
  function execute(controller, angleVelocityFactor) {
    controller.addYRotationAngle(angleVelocityFactor);
  }
}

class AddZRotation
  extends ViewAngleKeyEventHandler
{
  function execute(controller, angleVelocityFactor) {
    controller.addZRotationAngle(angleVelocityFactor);
  }
}

class AddFieldOfViewAngle
  extends ViewAngleKeyEventHandler
{
  function execute(controller, angleVelocityFactor) {
    controller.addFieldOfViewAngle(angleVelocityFactor);
  }
}

// === Tab: let conversion method ===
// let update: 1. Oct. 2017

