// for converting directly without creating instances
function cielabColor(lValue, aValue, bValue) {
  // D65/2° standard illuminant.
  let tristimulusValueX = 0.95047;
  let tristimulusValueY = 1.00000;
  let tristimulusValueZ = 1.08883;

  let yFactor = (lValue + 16.0) / 116.0;
  let xFactor = yFactor + aValue / 500.0;
  let zFactor = yFactor - bValue / 200.0;

  let xValue = constrain(tristimulusValueX * toXyzColorFunc(xFactor), 0.0, 1.0);
  let yValue = constrain(tristimulusValueY * toXyzColorFunc(yFactor), 0.0, 1.0);
  let zValue = constrain(tristimulusValueZ * toXyzColorFunc(zFactor), 0.0, 1.0);

  let redFactor =   ( 3.2404542 * xValue - 1.5371385 * yValue - 0.4985314 * zValue);
  let greenFactor = (-0.9692660 * xValue + 1.8760108 * yValue + 0.0415560 * zValue);
  let blueFactor =  ( 0.0556434 * xValue - 0.2040259 * yValue + 1.0572252 * zValue);

  return color(degamma(constrain(redFactor, 0.0, 1.0)) * 255.0, degamma(constrain(greenFactor, 0.0, 1.0)) * 255.0, degamma(constrain(blueFactor, 0.0, 1.0)) * 255.0);
}

function toXyzColorFunc(value) {
  let delta = 6.0 / 29.0;
    if (value > delta) return value * value * value;
    else return (value - 16.0 / 116.0) * 3.0 * delta * delta;
}

function degamma(value) {
  if (value <= 0.0031308) return 12.92 * value;
  else return 1.055 * pow(value, 1.0 / 2.4) - 0.055;
}

